// Generates docs/generated/{SCHEMA,API,SURFACES}.md deterministically from source ASTs.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
	discoverApiRoutes,
	discoverAppManifests,
	discoverSchemaTables,
} from './lib/repo-introspect.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT_DIR = path.join(ROOT, 'docs/generated');
const isCheckMode = process.argv.includes('--check');

const HEADER =
	'<!-- GENERATED by scripts/gen-docs.mjs — do not edit by hand. Run `pnpm gen:apps` to refresh. -->\n\n';

function renderSchemaDoc(tables) {
	const lines = [
		HEADER + '# Generated PostgreSQL Schema Reference',
		'',
		`Total tables discovered from \`src/db/**\`: **${tables.length}**`,
		'',
		'| Table | Columns | Indexes | Defined In |',
		'| :--- | ---: | ---: | :--- |',
		...tables.map((t) => `| \`${t.name}\` | ${t.columns.length} | ${t.indexes.length} | \`${t.sourceFile}\` |`),
		'',
	];

	for (const t of tables) {
		lines.push(`## \`${t.name}\``, '');
		lines.push(`Source: \`${t.sourceFile}\``, '');
		lines.push('| Column | Type | Constraints |', '| :--- | :--- | :--- |');
		for (const c of t.columns) {
			const safeConstraints = (c.constraints || '—').replace(/\|/g, '\\|');
			lines.push(`| \`${c.name}\` | \`${c.type}\` | ${safeConstraints} |`);
		}
		if (t.indexes.length > 0) {
			lines.push('', '**Indexes:**');
			for (const idx of t.indexes) {
				lines.push(`- \`${idx.name}\`${idx.unique ? ' (UNIQUE)' : ''}: \`${idx.definition}\``);
			}
		}
		lines.push('');
	}
	return lines.join('\n');
}

function renderApiDoc(routes) {
	const lines = [
		HEADER + '# Generated REST & SSE API Inventory',
		'',
		`Total route handlers discovered under \`src/app/api/**/route.ts\`: **${routes.length}**`,
		'',
		'| Endpoint | Methods | Audit Actions (`withAudit`) | Auth Guards | Source |',
		'| :--- | :--- | :--- | :--- | :--- |',
	];

	for (const r of routes) {
		const methods = r.methods.length ? r.methods.map((m) => `\`${m}\``).join(', ') : '—';
		const auditEntries = Object.entries(r.auditActions);
		const audit = auditEntries.length
			? auditEntries.map(([m, a]) => `\`${m}:${a.action}\``).join(', ')
			: '—';
		const guards = r.authGuards.length ? r.authGuards.map((g) => `\`${g}\``).join(', ') : 'public/custom';
		lines.push(`| \`${r.path}\` | ${methods} | ${audit} | ${guards} | \`${r.file}\` |`);
	}
	lines.push('');
	return lines.join('\n');
}

function renderSurfacesDoc(manifests, cliSrc, gateFiles) {
	const cmdMatch = cliSrc.match(/commands:\s*\[([^\]]+)\]/);
	const cliCommands = cmdMatch
		? [...cmdMatch[1].matchAll(/'([^']+)'/g)].map((m) => m[1])
		: [];

	const lines = [
		HEADER + '# Generated Application Surfaces, CLI & Verification Gates',
		'',
		`Total registered app manifests under \`src/apps/*/manifest.ts\`: **${manifests.length}**`,
		'',
		'## 1. Mini-Application Manifests',
		'',
		'| App ID | English Title | Category | Windowed | Dock Order | Use / Manage Permission Summary |',
		'| :--- | :--- | :--- | :--- | ---: | :--- |',
	];

	for (const m of manifests) {
		const title = m.en?.title || m.title;
		const windowed = m.window ? `Yes (${m.window.width}x${m.window.height})` : 'No';
		const dockOrder = typeof m.dock === 'number' ? m.dock : '—';
		const perm = `${m.permission.use} / ${m.permission.manage}`.replace(/\|/g, '\\|');
		lines.push(`| \`${m.id}\` | ${title} | ${m.category || 'System'} | ${windowed} | ${dockOrder} | ${perm} |`);
	}

	lines.push(
		'',
		'## 2. `./bin/orbit` CLI Commands (`scripts/orbit-cli.mjs`, `scripts/cli/format.mjs`)',
		''
	);
	for (const cmd of cliCommands) {
		lines.push(`- \`./bin/orbit ${cmd}\``);
	}

	lines.push('', '## 3. Active Verification & Codegen Gates', '');
	for (const g of gateFiles) {
		lines.push(`- \`${g}\``);
	}
	lines.push('');
	return lines.join('\n');
}

export async function run() {
	const tables = discoverSchemaTables(ROOT);
	const routes = discoverApiRoutes(
		ROOT,
		tables.map((t) => t.name)
	);
	const manifests = await discoverAppManifests(ROOT);
	const cliSrc = fs.readFileSync(path.join(ROOT, 'scripts/cli/format.mjs'), 'utf8');
	const gateFiles = fs
		.readdirSync(path.join(ROOT, 'scripts'))
		.filter((f) => /^(?:check-|gen-).*\.mjs$|^verify-ast\.mjs$/.test(f))
		.sort()
		.map((f) => `scripts/${f}`);

	const outputs = {
		[path.join(OUT_DIR, 'SCHEMA.md')]: renderSchemaDoc(tables),
		[path.join(OUT_DIR, 'API.md')]: renderApiDoc(routes),
		[path.join(OUT_DIR, 'SURFACES.md')]: renderSurfacesDoc(manifests, cliSrc, gateFiles),
	};

	if (isCheckMode) {
		const stale = Object.entries(outputs)
			.filter(([file, content]) => !fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== content)
			.map(([file]) => path.relative(ROOT, file));
		if (stale.length > 0) {
			console.error(`gen-docs: ${stale.join(', ')} out of date — run \`node scripts/gen-docs.mjs\``);
			process.exit(1);
		}
		console.log(
			`gen-docs: ${tables.length} tables, ${routes.length} routes, ${manifests.length} surfaces up to date`
		);
		return;
	}

	fs.mkdirSync(OUT_DIR, { recursive: true });
	for (const [file, content] of Object.entries(outputs)) {
		if (fs.existsSync(file) && fs.readFileSync(file, 'utf8') === content) continue;
		fs.writeFileSync(file, content, 'utf8');
	}
	console.log(
		`gen-docs: generated docs/generated/{SCHEMA,API,SURFACES}.md (${tables.length} tables, ${routes.length} routes, ${manifests.length} surfaces)`
	);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
	run().catch((err) => {
		console.error(err);
		process.exit(1);
	});
}
